const names=['CATIA PETRACCIA','KANWAR BRAR','GEORGE CHAN','Paul Mitrovich','ANNE ZID','TONYA PINKERTON','Roshan Anandappa','ABID SYED IFTIKHAR','Gina Gratta','Jassi Walia',"MICHAEL O'BRIEN",'SUSAN TAYLOR','FARAH PANAHI','RANDY RANDHAWA','ALLIE REMPEL','RON CARROLL','LARYSSA PALIN','CATHARINE ANN BARROW','Iryna Koyeva','Darla Youldon','Vanessa King','Maya Maria Lavor','Robert Miles','Jennifer Quick','EVA PYRA','Patricia Graham','ASHWIN RATHOD','CRAIG BARRAGER','SADHANA SANGLI','HARITH KHADHOORI','LIBERTAD MARTINEZ','NICOLE WILLIAMS','SABINA KOUTROS','LILY DO','Adrian Cox','PRAKASH BHARUCHA','VOULI TSONTZIDIS','MARY TRAN','VALERIE ANGALENA OURUMIS','REET SETHI','PURVIS MIRZA','AVI SAMAROO','Amanda Davis',"CLIFFORD D'SOUZA",'OLGA KUDRYAVTSEVA','HEESUNG NA','Pooja Gupta']
const urls={};const plans=[]
for(const name of names){const t=s.threads.find(t=>t.contact.name===name);if(!t)throw Error('Missing '+name);const c=t.contact,first=name.split(' ')[0].toLowerCase().replace(/^./,x=>x.toUpperCase());if(!urls[c.city])urls[c.city]=await asset(c.city);let body=`Here you go, ${first}! Here's our ${c.city} card. Feel free to save it and share it when a client needs moving help.`;
 if(name==='Jennifer Quick')body="Here you go, Jen! Our Hamilton card is attached. We provide binding estimates once the move details are confirmed. Pricing depends on the inventory, pickup and delivery locations, distance, stairs or elevator access, and any packing needed. Clients can reach our quote team at 437-782-3004 for an estimate for their move.";
 if(name==='SADHANA SANGLI'){if(!c.notes.includes('source_key=realtor-ca:2160062'))throw Error('Source mismatch');body="Hi Sadhana! I found your business contact details through your public REALTOR.ca agent profile. Our Mississauga card is attached. Pricing depends on what's being moved, the pickup and delivery locations, distance, stairs or elevator access, and packing. We provide a binding estimate once those details are confirmed, rather than one price for every move. If you have a particular move in mind, send me the date, route and rough inventory and we can work out an estimate.";}
 if(name==='OLGA KUDRYAVTSEVA')body="Here you go, Olga! We cover Toronto and the areas north of Toronto too. Here's our Toronto card for you to keep handy and share when a client needs moving help.";
 if(name==='Adrian Cox')body="Thanks Adrian, I'd be happy to work together! Here's our Mississauga card for you to save and share when a client needs moving help.";
 if(name==='TONYA PINKERTON')body="Hi Tonya! Here's our Toronto card. Happy to connect, and feel free to pass it along when a client needs moving help.";
 plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:t.touches.at(-1).id,from:'+14374650584',body,media_urls:[urls[c.city]],note:name==='SADHANA SANGLI'?'Requested card, pricing factors, and recorded REALTOR.ca source explained. No automatic follow-up.':'Requested correct-city card sent; question answered where applicable. No automatic follow-up.'});}
await fs.writeFile(dir+'/evening-card-plan.json',JSON.stringify({comparisons:['September 29 requested city cards once','September FAQ binding estimates and recorded source provenance','October 6 first reply pass; no nudge after thanks'],plans},null,2));
console.log(JSON.stringify({prepared:plans.length,cities:Object.keys(urls)}));
